package practice.concurrency.multithreadedfizzbuzz;
import static org.junit.jupiter.api.Assertions.*; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.*;
class FizzBuzzTest { @Test @Timeout(3) void emitsInOrder() throws Exception { var f=new FizzBuzz(5); var out=Collections.synchronizedList(new ArrayList<String>()); try(var e=Executors.newFixedThreadPool(4)){ e.submit(()->run(()->f.fizz(()->out.add("fizz")))); e.submit(()->run(()->f.buzz(()->out.add("buzz")))); e.submit(()->run(()->f.fizzbuzz(()->out.add("fizzbuzz")))); e.submit(()->run(()->f.number(n->out.add(""+n)))); e.shutdown(); e.awaitTermination(2,TimeUnit.SECONDS); } assertEquals(List.of("1","2","fizz","4","buzz"),out); } private static void run(Action a){try{a.run();}catch(InterruptedException e){Thread.currentThread().interrupt();}} interface Action{void run()throws InterruptedException;} }
